import{evaluateSemanticErrorRules}from"./rule.js";import{extractErrorSignals}from"./signals.js";import{GATEWAY_RULES}from"./rules/gateway.js";import{MODEL_PROVIDER_RULES}from"./rules/model-provider.js";import{SANDBOX_RULES}from"./rules/sandbox.js";import{SYSTEM_RULES}from"./rules/system.js";import{WORKFLOW_RULES}from"./rules/workflow.js";const CATALOG=[...GATEWAY_RULES,...MODEL_PROVIDER_RULES,...WORKFLOW_RULES,...SANDBOX_RULES,...SYSTEM_RULES];function summarizeKnownError(e){return evaluateSemanticErrorRules(CATALOG,extractErrorSignals(e))}export{summarizeKnownError};